/* Golden Braid AIDM B1 S18 Zombie — test cases
FILE: MonsterTestCase_Mentzer_Basic_Zombie_Insert.sql
TARGET: DnD.[Test].[MonsterTestCase] (PEQUOD SQL Server 2016+)
SOURCE: 1983 Mentzer Basic Dungeon Masters Rulebook, Zombie printed p.39.
B1 stocklist selects species only; synthetic encounter is independent.
2026-11-22. Idempotent insert-only; Specified/SourceChecked NOT execution, approval or UAT.
*/
USE [DnD];
GO
IF OBJECT_ID(N'Test.MonsterTestCase',N'U') IS NULL THROW 57182,'Test.MonsterTestCase missing',1;
IF NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestScenario] WHERE [ScenarioCode]=N'ZOMBIE-T001') THROW 57183,'ZOMBIE-T001 missing: deploy scenario first',1;
GO
SET XACT_ABORT ON;
GO
BEGIN TRY
 BEGIN TRAN;
 DECLARE @Seed TABLE ([ScenarioCode] NVARCHAR(MAX) NOT NULL,[TestCaseCode] NVARCHAR(MAX) NOT NULL,[SequenceNo] INT NOT NULL,[TestName] NVARCHAR(MAX) NOT NULL,[TestPhase] NVARCHAR(MAX) NOT NULL,[TestStatus] NVARCHAR(MAX) NOT NULL,[TestRevision] INT NOT NULL,[GivenText] NVARCHAR(MAX) NOT NULL,[ExpectedText] NVARCHAR(MAX) NOT NULL,[DiceFixtureJson] NVARCHAR(MAX) NULL,[AdditionalDataJson] NVARCHAR(MAX) NULL,[LinkedStoryRef] NVARCHAR(MAX) NULL,[AutomatedTestRef] NVARCHAR(MAX) NULL,[Notes] NVARCHAR(MAX) NULL);
 INSERT INTO @Seed ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes]) VALUES
 (N'ZOMBIE-T001',N'ZOM-C01',1,N'2 HD attack profile',N'COMBAT',N'Specified',1,N'A Zombie has a lawful target within claw range and rolls an attack.',N'Use the 2-HD monster attack row; only one attack per eligible round.',N'{"attack_d20":15}',N'{"armor_class":8,"hit_dice":2,"attacks_per_round":1}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C02',2,N'Claw on hit deals 1d8',N'COMBAT',N'Specified',1,N'ZOM-T001-1 claw attack hits a character; d8 damage result 6.',N'Deal exactly 6 HP damage; no weapon lookup or second attack.',N'{"attack_d20":19,"claw_damage_d8":6}',N'{"expected_damage":6}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C03',3,N'A missed claw does no damage',N'COMBAT',N'Specified',1,N'ZOM-T001-2 makes a claw attack and misses.',N'Inflict no HP damage, no secondary effects and no invented disease.',N'{"attack_d20":1}',N'{"expected_damage":0}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C04',4,N'Equipped sword follows weapon damage mode',N'COMBAT',N'Specified',1,N'ZOM-T001-3 has a normal sword and hits a valid target.',N'Use generic 1d6 standard weapon damage or sword 1d8 approved variable mode; no extra Zombie damage bonus.',N'{"standard_d6":4,"variable_sword_d8":7}',N'{"standard_damage":4,"variable_damage":7}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C05',5,N'Monster HP and save profile stay authoritative',N'COMBAT',N'Specified',1,N'Each Zombie actor is independent, with source HD2, Fighter1 save, AC8 and HP 7/8/10/9.',N'Resolve combat independently per actor; 34 total starting HP, without importing stocked B1 HP.',NULL,N'{"starting_hp":[7,8,10,9],"total_hp":34,"armor_class":8,"save_as":"Fighter 1"}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C06',6,N'Ordinary combatants precede delayed Zombies',N'COMBAT',N'Specified',1,N'Both sides roll normal side initiative; an ordinary player acts against a surviving Zombie.',N'Ordinary eligible combatant actions occur before delayed Zombie actions regardless of which side has higher d6.',N'{"party_initiative_d6":2,"zombie_side_initiative_d6":6}',N'{"order":["ordinary","delayed"],"zombie_has_separate_roll":false}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C07',7,N'Higher side initiative acts first within delayed group',N'COMBAT',N'Specified',1,N'Both sides have eligible delayed actors; party side rolls 6, Zombie side rolls 3.',N'Within the delayed group, eligible delayed actors on party side act before Zombies.',N'{"party_initiative_d6":6,"zombie_side_initiative_d6":3}',N'{"delayed_order":["party","zombies"]}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C08',8,N'Initiative tie means simultaneous delayed actions',N'COMBAT',N'Specified',1,N'Zombie side and party side delayed actors tie their initiative dice.',N'Delayed opposing actions resolve simultaneously, including mutual lethal attacks; not arbitrary order.',N'{"party_initiative_d6":4,"zombie_side_initiative_d6":4}',N'{"simultaneous_delayed":true}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C09',9,N'Two-handed weapons share delayed group',N'COMBAT',N'Specified',1,N'A non-Zombie combatant actually uses a two-handed weapon while a Zombie is present.',N'Place the two-handed user in the delayed group with Zombies; don''t give that character a normal-order attack or an extra initiative die.',N'{"party_initiative_d6":5,"zombie_side_initiative_d6":2}',N'{"two_handed_is_delayed":true,"zombie_is_delayed":true}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C10',10,N'Sleep spell does not affect undead Zombie',N'COMBAT',N'Specified',1,N'Sleep targets one or more Zombies in spell area.',N'Zombies are unaffected by Sleep. Do not assign ASLEEP or remove an eligible action due to Sleep.',NULL,N'{"species":"ZOMBIE","immune_to":"SLEEP"}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C11',11,N'Charm spell does not affect undead Zombie',N'COMBAT',N'Specified',1,N'Charm targets a Zombie and an affected target would otherwise change allegiance.',N'Zombies are unaffected by Charm. Do not assign CHARMED.',NULL,N'{"species":"ZOMBIE","immune_to":"CHARM"}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C12',12,N'No invented Poison or disease from Zombie attack',N'COMBAT',N'Specified',1,N'A Zombie successfully strikes a living character with an ordinary claw or sword.',N'Apply only actual claw or weapon damage. No POISONED, DISEASED, infection or conversion state is created; don''t assume unsupported broad poison immunity for the Zombie.',N'{"claw_damage_d8":5}',N'{"disease_status":false,"poisoned_status":false,"zombie_transformation":false}',N'AIDM-DES-001.7',NULL,N'No unsupported broad Zombie poison immunity is asserted by the Basic monster entry.'),
 (N'ZOMBIE-T001',N'ZOM-C13',13,N'Weapon damage and dying before action',N'COMBAT',N'Specified',1,N'A Zombie with an unspent delayed action takes sufficient valid ordinary weapon damage to reduce it to 0 HP.',N'Apply damage using canonical weapons; destroyed Zombie cannot make a later delayed attack unless simultaneous-resolution rules explicitly preserve that attack.',N'{"attack_damage":7}',N'{"destroyed_zombie_may_act_later":false}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-C14',14,N'Morale 12, no invented morale checks',N'COMBAT',N'Specified',1,N'A source-supported normal morale-check point occurs while a Zombie guards an object.',N'Use morale 12 under normal Mentzer morale procedure; no flee result and no special extra morale roll from artwork.',N'{"morale_2d6":[6,6]}',N'{"morale":12}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-E01',15,N'Independent count and HP fixture',N'ENCOUNTER',N'Specified',1,N'Encounter selects Zombie species using B1 S18 only; synthetic count roll yields 4; HP rolls are fixed.',N'Produce four independent actor identities with 2d8 HP 7,8,10,9, total 34; two claw and two sword loadouts; no B1 stocked HP.',N'{"count_d8":4,"hp_2d8":[[3,4],[3,5],[6,4],[5,4]]}',N'{"count":4,"hp":[7,8,10,9],"total_hp":34}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-E02',16,N'One normal surprise die per side',N'ENCOUNTER',N'Specified',1,N'The torchlit guard scene begins with party surprise 5 and Zombie side surprise 4.',N'Neither side is surprised; never roll one surprise check per Zombie or create Zombie-specific surprise bonuses.',N'{"party_surprise_d6":5,"zombie_surprise_d6":4}',N'{"party_surprised":false,"zombies_surprised":false}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-E03',17,N'Surprise opening is determined by Encounter',N'ENCOUNTER',N'Specified',1,N'Independent branch: party surprise d6=5 and Zombie side d6=1.',N'Encounter marks Zombies surprised and passes opening/surprise facts to Combat; does not replace or reorder normal Combat initiative.',N'{"party_surprise_d6":5,"zombie_surprise_d6":1}',N'{"party_surprised":false,"zombies_surprised":true}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-E04',18,N'Standing coffer guard order drives actions',N'ENCOUNTER',N'Specified',1,N'Four mindless Zombies are stationed by a coffer with a standing order to stop intruders.',N'Encounter uses simple standing order, party actions and actual scene triggers; no invented broad strategy, negotiation or omniscient pursuit.',NULL,N'{"guarded_object":"coffer","standing_order":true}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-E05',19,N'Mindless behaviour and no invented contagion',N'ENCOUNTER',N'Specified',1,N'Party approaches, attempts distraction or retreat, and Zombies observe under their guard order.',N'Represent undirected mindless behaviour faithfully; allow DM to interpret finite orders, movement and player intention, without spontaneous disease or forced conversion.',NULL,N'{"mindless":true,"contagion":false}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-E06',20,N'Treasure Nil; coffer belongs to scene',N'ENCOUNTER',N'Specified',1,N'The approved illustration shows Zombies protecting an iron-banded coffer.',N'Zombie species carries no Treasure Type award (Nil); any coffer contents must be explicit separately in Encounter/Adventure, not inferred from the image.',NULL,N'{"treasure_type":"Nil","coffer_contents_known":false}',N'AIDM-DES-001.7',NULL,N'No tests executed.'),
 (N'ZOMBIE-T001',N'ZOM-L01',21,N'Cleric Turn Undead integration',N'DEFERRED_LIFECYCLE',N'Deferred',1,N'A Cleric attempts to Turn a Zombie during a future integrated encounter.',N'Future shared Turning subsystem resolves Zombie as undead and propagates lawful outcome to Combat/Encounter; not executed in S18 fixed test.',NULL,N'{"monster_kind":"undead","turning_story":"AIDM-DES-001.7.10"}',N'AIDM-DES-001.7.10',NULL,N'No tests executed.');
 INSERT INTO [Test].[MonsterTestCase] ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes])
 SELECT s.[ScenarioCode],s.[TestCaseCode],s.[SequenceNo],s.[TestName],s.[TestPhase],s.[TestStatus],s.[TestRevision],s.[GivenText],s.[ExpectedText],s.[DiceFixtureJson],s.[AdditionalDataJson],s.[LinkedStoryRef],s.[AutomatedTestRef],s.[Notes] FROM @Seed AS s
 WHERE NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestCase] AS t WITH(UPDLOCK,HOLDLOCK) WHERE t.[ScenarioCode]=s.[ScenarioCode] AND t.[TestCaseCode]=s.[TestCaseCode]);
 PRINT CONCAT(N'Inserted Zombie test definitions: ',@@ROWCOUNT);
 COMMIT;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
GO
SELECT [ScenarioCode],[TestPhase],[TestStatus],COUNT(*) AS [TestCount] FROM [Test].[MonsterTestCase]
WHERE [ScenarioCode]=N'ZOMBIE-T001' GROUP BY [ScenarioCode],[TestPhase],[TestStatus]
ORDER BY [TestPhase],[TestStatus];
GO
